["name"] = "Walton",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
["type"] = "MONSTER_SAY",
},
["color"] = {
["r"] = 1,
["g"] = 1,
["b"] = 0.6235294342041016,
},
["text"] = "Walton says: I thought you were dead, Terry.",
["timestamp"] = 1795586892,
["id"] = "s10_4998",
},
{
["recordedBy"] = "Simonhunter-Windseeker",
["typeInfo"] = {
["player"] = {
["name"] = "Terry Longdrink",
},
["event"] = "CHAT_MSG_MONSTER_SAY",
