\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_SKILL\",\"type\":\"SKILL\"},\"color\":{\"b\":1,\"g\":0.3333333432674408,\"r\":0.3333333432674408},\"text\":\"Your skill in Defense has increased to 39.\",\"id\":\"s1_4895\",\"timestamp\":1794544050},{\"recordedBy\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Hungry Bandit\"},\"event\":\"CHAT_MSG_MONSTER_EMOTE\",\"type\":\"MONSTER_EMOTE\"},\"color\":{\"b\":0.250980406999588,\"g\":0.501960813999176,\"r\":1},\"text\":\"Hungry Bandit attempts to run away in fear!\",\"id\":\"s1_4896\",\"timestamp\":1794544056},{\"recordedBy\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_SKILL\",\"type\":\"SKILL\"},\"color\":{\"b\":1,\"g\":0.3333333432674408,\"r\":0.3333333432674408},\"text\":\"Your skill in Swords has increased to 37.\",\"id\":\"s1_4897\",\"timestamp\":1794544057},{\"recordedBy\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"player\":{\"race\":\"Skyborne\",\"name\":\"Simonhunter Windseeker\",\"sex\":3,\"class\":\"HUNTER\",\"level\":9},\"event\":\"CHAT_MSG_LOOT\",\"type\":\"LOOT\"},\"color\":{\"b\":0,\"g\":0.6666666865348816,\"r\":0},\"text\":\"You receive loot: |cnIQ1:|Hitem:252028::::::::9:1485:::::::::|h[Fresh Gustberry Bread]|h|r\",\"id\":\"s1_4898\",\"timestamp\":1794544060},{\"recordedBy\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"event\":\"CHAT_MSG_MONEY\",\"type\":\"MONEY\"},\"color\":{\"b\":0,\"g\":1,\"r\":1},\"text\":\"You loot 8 Copper\",\"id\":\"s1_4899\",\"timestamp\":1794544061},{\"recordedBy\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Ferauu the Bludgeon\"},\"event\":\"CHAT_MSG_MONSTER_SAY\",\"type\":\"MONSTER_SAY\"},\"color\":{\"b\":0.6235294342041016,\"g\":1,\"r\":1},\"text\":\"Ferauu the Bludgeon says: Aamelia, my dear. Where's Alvarion? Too afraid to come and face Ferauu, so he sent you?\",\"id\":\"s1_4900\",\"timestamp\":1794544063},{\"recordedBy\":\"Simonhunter-Windseeker\",\"typeInfo\":{\"player\":{\"name\":\"Aamelia Windfield\"},